using System.Text.Json;
using var probe=new NebulaPalette();
if(args[0]=="--snr-metadata"){probe.ReadSnr(int.Parse(args[1]));var runtime=(Microsoft.Diagnostics.Runtime.ClrRuntime)typeof(NebulaPalette).GetField("runtime",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(probe)!;foreach(var module in runtime.EnumerateModules()){var type=module.GetTypeByName("SuperNewRoles.Modules.ExPlayerControl");if(type==null)continue;foreach(var domain in runtime.AppDomains){var f=type.GetStaticFieldByName("<_exPlayerControls>k__BackingField");Console.WriteLine(JsonSerializer.Serialize(new{module=module.Name,domain=domain.Name,initialized=f?.IsInitialized(domain),address=f?.GetAddress(domain),objectAddress=f?.ReadObject(domain).Address}));}}}
else if(args[0]=="--snr-watch"){var until=Environment.TickCount64+45000;string last="";while(Environment.TickCount64<until){var state=probe.ReadSnr(int.Parse(args[1]));var line=JsonSerializer.Serialize(new{meeting=state.MeetingCount,ready=state.WrapReady,players=state.FinalStates.Count});if(line!=last){Console.WriteLine(line);last=line;}Thread.Sleep(100);}}
else if(args[0]=="--snr-probe"){var state=probe.ReadSnr(int.Parse(args[1]));Console.WriteLine(JsonSerializer.Serialize(new{meeting=state.MeetingCount,ready=state.WrapReady,airship=state.AirshipWrapCount,players=state.FinalStates.Count,collateral=state.FinalStates.Values.Count(SnrObservation.IsCollateral),exiled=state.FinalStates.Values.Count(s=>s==5)}));}
else {probe.Read(int.Parse(args[1]));Console.WriteLine(JsonSerializer.Serialize(new{completedMeetings=probe.CompletedMeetings(),madmateCollateralCount=probe.MadmateCollateralDeaths(Enumerable.Range(0,32).ToHashSet()).Count}));}
